class AssessmentSystem:
    FAIL_THRESHOLD = 60

    def __init__(self):
        self.students = {}

    def add_student(self, name, grade, major):
        self.students[name] = {'name': name, 'grade': grade, 'major': major, 'courses': {}}

    def add_course_score(self, name, course, score):
        if name not in self.students:
            return
        self._get_student(name)['courses'][course] = score

    def _get_student(self, name):
        return self.students.get(name)

    def get_gpa(self, name):
        student = self._get_student(name)
        if student is None:
            return None
        courses = student['courses']
        if not courses:
            return None
        return sum(courses.values()) / len(courses)

    def get_all_students_with_fail_course(self):
        return [
            name for name, student in self.students.items()
            if self._has_fail_course(student['courses'])
        ]

    _has_fail_course = staticmethod(lambda courses: any(score < AssessmentSystem.FAIL_THRESHOLD for score in courses.values()))

    def get_course_average(self, course):
        total, count = 0, 0
        for student in self.students.values():
            score = student['courses'].get(course)
            if score is not None:
                total += score
                count += 1
        return total / count if count else None

    def get_top_student(self):
        top_student = None
        top_gpa = 0.0
        for name in self.students:
            gpa = self.get_gpa(name)
            if gpa is None:
                continue
            if gpa > top_gpa:
                top_gpa = gpa
                top_student = name
        return top_student
